import click
from click.testing import CliRunner
def test_inclusive_range():
    seen = []
    @click.command()
    @click.option('--count', type=click.IntRange(1, 3))
    def command(count):
        seen.append(count)
    for number in [0, 1, 3, 4]:
        seen.clear()
        result = CliRunner().invoke(command, ['--count', str(number)])
        assert result.exit_code == (0 if number in [1, 3] else 2)
        assert seen == ([number] if number in [1, 3] else [])
        assert all(type(value) is int for value in seen)
